-- Copiando estrutura do banco de dados para video_metadata
CREATE DATABASE IF NOT EXISTS "video_metadata";
;

-- Copiando estrutura para tabela video_metadata.chapters
CREATE TABLE IF NOT EXISTS chapters (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                video_id TEXT NOT NULL,
                chapter_index INTEGER NOT NULL,
                title TEXT NOT NULL,
                start_time REAL NOT NULL,
                end_time REAL NOT NULL,
                duration REAL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (video_id) REFERENCES videos (video_id) ON DELETE CASCADE,
                UNIQUE(video_id, chapter_index)
            );
;
CREATE INDEX idx_chapters_video_id ON chapters(video_id);

-- Copiando dados para a tabela video_metadata.chapters: -1 rows
/*!40000 ALTER TABLE "chapters" DISABLE KEYS */;
/*!40000 ALTER TABLE "chapters" ENABLE KEYS */;

-- Copiando estrutura para tabela video_metadata.download_history
CREATE TABLE IF NOT EXISTS download_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                video_id TEXT NOT NULL,
                download_type TEXT NOT NULL,  -- video, audio, thumbnail, storyboard
                format_id TEXT,
                local_path TEXT NOT NULL,
                file_size INTEGER,
                download_status TEXT NOT NULL,  -- completed, failed, in_progress, cancelled
                error_message TEXT,
                download_started TIMESTAMP,
                download_completed TIMESTAMP,
                download_duration REAL,  -- em segundos
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (video_id) REFERENCES videos (video_id) ON DELETE CASCADE
            );
CREATE INDEX idx_download_history_video_id ON download_history(video_id);
CREATE INDEX idx_download_history_status ON download_history(download_status);
CREATE INDEX idx_download_history_type ON download_history(download_type);

-- Copiando dados para a tabela video_metadata.download_history: -1 rows
/*!40000 ALTER TABLE "download_history" DISABLE KEYS */;
/*!40000 ALTER TABLE "download_history" ENABLE KEYS */;

-- Copiando estrutura para tabela video_metadata.storyboards
CREATE TABLE IF NOT EXISTS storyboards (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                video_id TEXT NOT NULL,
                storyboard_id TEXT NOT NULL,
                format_note TEXT,
                url TEXT NOT NULL,
                width INTEGER,
                height INTEGER,
                fps REAL,
                rows INTEGER,
                columns INTEGER,
                total_fragments INTEGER,
                resolution TEXT,
                local_path TEXT,  -- caminho local se baixado
                downloaded BOOLEAN DEFAULT FALSE,
                download_date TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (video_id) REFERENCES videos (video_id) ON DELETE CASCADE,
                UNIQUE(video_id, storyboard_id)
            );
;
CREATE INDEX idx_storyboards_video_id ON storyboards(video_id);

-- Copiando dados para a tabela video_metadata.storyboards: -1 rows
/*!40000 ALTER TABLE "storyboards" DISABLE KEYS */;
/*!40000 ALTER TABLE "storyboards" ENABLE KEYS */;

-- Copiando estrutura para tabela video_metadata.storyboard_fragments
CREATE TABLE IF NOT EXISTS storyboard_fragments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                storyboard_id INTEGER NOT NULL,
                fragment_index INTEGER NOT NULL,
                url TEXT NOT NULL,
                duration REAL,
                start_time REAL,
                end_time REAL,
                local_path TEXT,  -- caminho local se baixado
                downloaded BOOLEAN DEFAULT FALSE,
                download_date TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (storyboard_id) REFERENCES storyboards (id) ON DELETE CASCADE,
                UNIQUE(storyboard_id, fragment_index)
            );
;

