-- Copiando estrutura para tabela video_metadata.thumbnails
CREATE TABLE IF NOT EXISTS thumbnails (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                video_id TEXT NOT NULL,
                thumbnail_id TEXT NOT NULL,
                url TEXT NOT NULL,
                width INTEGER,
                height INTEGER,
                resolution TEXT,
                preference INTEGER,
                format_type TEXT,  -- jpg, webp, etc
                quality_level TEXT,  -- hq, mq, default
                local_path TEXT,  -- caminho local se baixado
                file_size INTEGER,
                downloaded BOOLEAN DEFAULT FALSE,
                download_date TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (video_id) REFERENCES videos (video_id) ON DELETE CASCADE,
                UNIQUE(video_id, thumbnail_id)
            );
;
CREATE INDEX idx_thumbnails_video_id ON thumbnails(video_id);
CREATE INDEX idx_thumbnails_quality ON thumbnails(quality_level);

