                width INTEGER,
                height INTEGER,
                fps REAL,
                vcodec TEXT,
                acodec TEXT,
                tbr REAL,
                vbr REAL,
                abr REAL,
                filesize_approx INTEGER,
                quality INTEGER,
                preference INTEGER,
                url TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (video_id) REFERENCES videos (video_id) ON DELETE CASCADE,
                UNIQUE(video_id, format_id)
            );
;
