-- Copiando estrutura para tabela video_metadata.video_metadata
CREATE TABLE IF NOT EXISTS video_metadata (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                video_id TEXT NOT NULL,
                fps REAL,
                width INTEGER,
                height INTEGER,
                aspect_ratio REAL,
                resolution TEXT,
                vcodec TEXT,
                acodec TEXT,
                filesize_approx INTEGER,
                tbr REAL,
                vbr REAL,
                abr REAL,
                format_note TEXT,
                quality TEXT,
                language TEXT,
                subtitles_available TEXT,  -- JSON object
                automatic_captions_available TEXT,  -- JSON object
